INSERT INTO players VALUES(25,'Marcus Rashford',NULL,NULL,NULL,NULL,'LW/CF','2025-02~05 맨유→빌라 임대(24-25 후반기). 이후 바르셀로나 임대(£26m 바이옵션). 에메리 좌측 인버티드 기용 선례의 기준 선수 — 레앙 등 동형 영입 평가 template (tactic_observations 래시포드 선례 참조).');
